    current = { component, props };
    cursor = 0;
    pending = [];
    dirty = false;
    component(props);
    const toRun = pending;
    for (const { slot } of toRun) {
      if (typeof slot.cleanup === "function") slot.cleanup();
      slot.cleanup = undefined;
    }
    for (const { slot, fn } of toRun) {
      const result = fn();
      slot.cleanup = typeof result === "function" ? result : undefined;
