  function flush() {
    if (!dirty || !current) return false;
    render(current.component, current.props);
    return true;
  }

  function unmount() {
    for (const slot of hooks) if (slot && typeof slot.cleanup === "function") slot.cleanup();
    hooks = [];
    current = null;
    dirty = false;
  }

  return { useState, useEffect, render, flush, unmount };
